; neg.asm -- chapter 9: NEG on every value of A
; generated by gen09.py
        INCLUDE "msx.inc"
        OUTPUT "neg.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
init:   di
        ld sp, SYS_AREA
TABLE   EQU $D000             ; A and F after NEG, two bytes a case
        ld hl, TABLE
        ld b, 0                 ; B: A before NEG, 0 to 255
next:   ld a, b
        neg                     ; A = 0 - A
        push af
        pop de                  ; D = A after, E = F after
        ld (hl), d
        inc hl
        ld (hl), e
        inc hl
        inc b
        jr nz, next
stop:   jr stop
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
